1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.regex.Pattern;
4	
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Normalizes an owner {@code telephone} to E.164 form. Spaces, dashes and brackets are stripped; a
9	 * value that already carries a leading {@code '+'} and country code keeps them, otherwise country
10	 * code {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
11	 * The result must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'} becomes
12	 * {@code '+61412345678'} and {@code '+64 21 123 456'} becomes {@code '+6421123456'}.
13	 */
14	final class OwnerTelephone {
15	
16	    /** E.164: a {@code '+'} followed by 8 to 15 digits. */
17	    private static final Pattern E164 = Pattern.compile("\\+[0-9]{8,15}");
18	
19	    /** Formatting characters removed before interpreting the number: spaces, dashes and brackets. */
20	    private static final Pattern FORMATTING = Pattern.compile("[\\s()\\-]");
21	
22	    private OwnerTelephone() {
23	    }
24	
25	    /**
26	     * @return the telephone in E.164 form.
27	     * @throws InvalidTelephoneException when the value cannot form a valid E.164 number.
28	     */
29	    static String toE164(String telephone) throws InvalidTelephoneException {
30	        if (telephone == null) {
31	            throw new InvalidTelephoneException(null);
32	        }
33	        String stripped = FORMATTING.matcher(telephone).replaceAll("");
34	        String e164;
35	        if (stripped.startsWith("+")) {
36	            e164 = stripped;
37	        } else {
38	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
39	            e164 = "+61" + national;
40	        }
41	        if (!E164.matcher(e164).matches()) {
42	            throw new InvalidTelephoneException(telephone);
43	        }
44	        return e164;
45	    }
46	}
