5	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
6	
7	/**
8	 * Normalizes the optional owner {@code email}. Email is absent when null or blank; when present it must
9	 * be a syntactically valid address, and is stored/returned lower-cased.
10	 */
11	final class OwnerEmail {
12	
13	    /**
14	     * A pragmatic syntactic check: a non-empty local part, a single {@code @}, and a domain carrying at
15	     * least one dot, none of the three parts containing whitespace or an {@code @}.
16	     */
17	    private static final Pattern SYNTAX = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
18	
19	    private OwnerEmail() {
20	    }
21	
22	    /**
23	     * @return the trimmed, lower-cased email, or {@code null} when it is absent (null or blank).
24	     * @throws InvalidEmailException when present but not syntactically valid.
25	     */
26	    static String normalize(String email) throws InvalidEmailException {
27	        if (email == null || email.isBlank()) {
28	            return null;
29	        }
30	        String trimmed = email.trim();
31	        if (!SYNTAX.matcher(trimmed).matches()) {
32	            throw new InvalidEmailException(email);
33	        }
34	        return trimmed.toLowerCase();
35	    }
36	}
